import json, re, pathlib
root=pathlib.Path('/root/DATA/products')
for fname in ['CoachForce.json','PersonalizeForce.json']:
    data=json.loads((root/fname).read_text())
    text=json.dumps(data)
    for kw in ['Market Research','market research','competitor','strength','weakness','demo','URL','http']:
        if kw.lower() in text.lower():
            pass
    print(fname,'keys',list(data.keys())[:20])
    # find docs with 'Market Research Report'
    def find(obj, path=''):
        if isinstance(obj, dict):
            for k,v in obj.items():
                p=f'{path}.{k}' if path else k
                if isinstance(v,(dict,list)):
                    yield from find(v,p)
                else:
                    if isinstance(v,str) and 'Market Research Report' in v:
                        yield (p,v)
        elif isinstance(obj, list):
            for i,v in enumerate(obj):
                p=f'{path}[{i}]'
                if isinstance(v,(dict,list)):
                    yield from find(v,p)
                else:
                    if isinstance(v,str) and 'Market Research Report' in v:
                        yield (p,v)
    hits=list(find(data))
    print('  Market Research Report hits',len(hits))
    for p,v in hits[:10]:
        print('   ',p,':',v)
