    if 'competitor product' in txt.lower():
        # Heuristic: competitor name after 'about' or '@here take a look at'
        m=re.search(r'about\s+([A-Za-z0-9_-]+)', txt)
        if m:
            competitor_names.add(m.group(1))
        m=re.search(r'take a look at\s+([A-Za-z0-9_-]+)', txt, re.I)
        if m:
            competitor_names.add(m.group(1))

# Fallback to known competitors from URLs if needed
if not competitor_names:
    competitor_names.update(['PersonaAI','SmartSuggest','TailorAI'])

insight_ids=[]
for msg in pers.get('slack',[]):
    txt=msg.get('Message',{}).get('User',{}).get('text','')
    low=txt.lower()
    if ('strength' in low or 'weakness' in low):
        if ('competitor' in low) or any(c.lower() in low for c in competitor_names):
            uid=msg.get('Message',{}).get('User',{}).get('userId')
            if uid and uid not in insight_ids:
                insight_ids.append(uid)

q2_answer=insight_ids

# ---------------- q3: competitor demo URLs shared ----------------
competitor_demo_urls=[]
for msg in pers.get('slack',[]):
    txt=msg.get('Message',{}).get('User',{}).get('text','')
