        elif isinstance(obj, list):
            for i,v in enumerate(obj):
                p=f'{path}[{i}]'
                if isinstance(v,(dict,list)):
                    yield from find(v,p)
                else:
                    if isinstance(v,str) and 'Market Research Report' in v:
