pers=json.loads((data_root/'products/PersonalizeForce.json').read_text())
emps=json.loads((data_root/'metadata/employee.json').read_text())

# ---------------- q1: CoachForce market research report authors + key reviewers ----------------
# Find latest Market Research Report doc (by date) in CoachForce product file
mrr_docs=[d for d in coach.get('documents',[]) if d.get('type')=='Market Research Report']
# Prefer those that are about CoachForce (renamed from CoFoAIX). Dataset evidence indicates CoFoAIX->CoachForce.
# We'll keep docs whose id contains 'cofoaix' since those are the only MRR docs.
co_docs=[d for d in mrr_docs if 'cofoaix' in (d.get('id','').lower())]
if not co_docs:
    co_docs=mrr_docs

def parse_dt(s):
    # ISO-ish timestamps
    import datetime as _dt
    try:
        return _dt.datetime.fromisoformat(s)
    except Exception:
        return _dt.datetime.min

latest_doc=max(co_docs, key=lambda d: parse_dt(d.get('date','')))
author_ids=[]
if 'author' in latest_doc:
    author_ids=[latest_doc['author']]
elif 'authors' in latest_doc:
    author_ids=list(latest_doc['authors'])

# Extract key reviewers from meeting transcript contributors (speaker turns), excluding the author
author_names=set()
for aid in author_ids:
    if aid in emps and isinstance(emps[aid], dict):
        author_names.add(emps[aid].get('name'))

reviewer_names=[]
for mt in coach.get('meeting_transcripts',[]):
    if mt.get('document_type')=='Market Research Report':
        tr=mt.get('transcript','')
        for line in tr.splitlines():
            m=re.match(r'^([A-Za-z]+(?:\s+[A-Za-z]+)*)\s*:\s', line)
            if m:
                name=m.group(1).strip()
                if name and name not in author_names and name not in reviewer_names:
                    reviewer_names.append(name)

# Map names to IDs (keep only resolvable)
name_to_ids={v.get('name'):k for k,v in emps.items() if isinstance(v,dict) and v.get('name')}
reviewer_ids=[name_to_ids[n] for n in reviewer_names if n in name_to_ids]

q1_answer=author_ids + reviewer_ids

# ---------------- q2: PersonalizeForce competitor strengths/weakness insights contributors ----------------
competitor_names=set()
for msg in pers.get('slack',[]):
    txt=msg.get('Message',{}).get('User',{}).get('text','')
    if 'competitor product' in txt.lower():
        # Heuristic: competitor name after 'about' or '@here take a look at'
        m=re.search(r'about\s+([A-Za-z0-9_-]+)', txt)
        if m:
            competitor_names.add(m.group(1))
        m=re.search(r'take a look at\s+([A-Za-z0-9_-]+)', txt, re.I)
        if m:
            competitor_names.add(m.group(1))

# Fallback to known competitors from URLs if needed
if not competitor_names:
    competitor_names.update(['PersonaAI','SmartSuggest','TailorAI'])

insight_ids=[]
for msg in pers.get('slack',[]):
    txt=msg.get('Message',{}).get('User',{}).get('text','')
    low=txt.lower()
    if ('strength' in low or 'weakness' in low):
        if ('competitor' in low) or any(c.lower() in low for c in competitor_names):
            uid=msg.get('Message',{}).get('User',{}).get('userId')
            if uid and uid not in insight_ids:
                insight_ids.append(uid)

q2_answer=insight_ids

# ---------------- q3: competitor demo URLs shared ----------------
competitor_demo_urls=[]
for msg in pers.get('slack',[]):
    txt=msg.get('Message',{}).get('User',{}).get('text','')
    low=txt.lower()
    if 'demo' in low and ('http://' in low or 'https://' in low):
        for u in re.findall(r'https?://\S+', txt):
            u=u.rstrip(').,>')
            if 'sf-internal.slack.com' in u:
                continue
            if u not in competitor_demo_urls:
                competitor_demo_urls.append(u)

q3_answer=competitor_demo_urls

# ---------------- token estimation ----------------
# Approximate tokens: 1 token ~ 4 chars (rough); include serialized answer only.

def est_tokens(obj):
    s=json.dumps(obj, ensure_ascii=False)
    return int(math.ceil(len(s)/4))

out={
    'q1': {'answer': q1_answer, 'tokens': est_tokens(q1_answer)},
    'q2': {'answer': q2_answer, 'tokens': est_tokens(q2_answer)},
    'q3': {'answer': q3_answer, 'tokens': est_tokens(q3_answer)},
}

path=pathlib.Path('/root/answer.json')
path.write_text(json.dumps(out, indent=4, ensure_ascii=False))
print('wrote',path)
print(json.dumps(out, indent=2, ensure_ascii=False))
